package com.funnywork;
import jakarta.validation.constraints.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import java.time.Clock;
import java.util.*;
import java.util.concurrent.Semaphore;

/** Office creation changes only authorized task artifacts, never an external business system or local file. */
@Service
public class OfficeTools {
    public record Call(@Min(1) long epoch,@NotNull @Pattern(regexp="[a-f0-9]{64}") String requestKey,@NotNull @Size(max=8) Map<String,Object> arguments){}
    private final JdbcTemplate db;private final AuthService auth;private final TenantLocks locks;private final ControlService control;private final ToolRegistry tools;
    private final ModelExecution model;private final ArtifactService artifacts;private final OfficeDocuments documents;private final Json json;private final Clock clock;private final TransactionTemplate tx;
    private final Semaphore capacity=new Semaphore(4);
    public OfficeTools(JdbcTemplate db,AuthService auth,TenantLocks locks,ControlService control,ToolRegistry tools,ModelExecution model,ArtifactService artifacts,OfficeDocuments documents,Json json,Clock clock,PlatformTransactionManager manager){this.db=db;this.auth=auth;this.locks=locks;this.control=control;this.tools=tools;this.model=model;this.artifacts=artifacts;this.documents=documents;this.json=json;this.clock=clock;tx=new TransactionTemplate(manager);}
    private record Access(ControlService.ModelLease lease,ToolContract contract,Map<String,Object> input,Map<String,Object> source){}
    private Access access(Identity node,String attempt,String toolId,Call body){return tx.execute(status->{locks.lock(node.tenant());var lease=control.modelLease(node,attempt,body.epoch(),false);var contract=tools.authorizedVersion(lease.owner(),lease.taskId(),toolId).contract();if(!BuiltinToolTemplates.isOfficeTool(contract))throw ApiException.forbidden();var input=contract.validate(body.arguments());Map<String,Object> source=input.containsKey("artifactId")?model.attachment(node,attempt,body.epoch(),(String)input.get("artifactId"),integer(input,"version",1,32)):null;return new Access(lease,contract,input,source);});}
    private int integer(Map<String,Object> input,String name,int min,int max){Object value=input.get(name);if(!(value instanceof Number n) || n.longValue()<min || n.longValue()>max)throw OfficeDocuments.invalid();return n.intValue();}
    public List<String> catalog(Identity node,String attempt,long epoch){return tx.execute(status->{locks.lock(node.tenant());var lease=control.modelLease(node,attempt,epoch,false);var result=new ArrayList<String>();for(var entry:tools.catalog(lease.owner(),lease.taskId())){var registered=tools.authorizedVersion(lease.owner(),lease.taskId(),(String)entry.get("toolVersionId"));if(BuiltinToolTemplates.isOfficeTool(registered.contract()))result.add(registered.id());}return result;});}
    public Map<String,Object> call(Identity node,String attempt,String toolId,Call body){
        var initial=access(node,attempt,toolId,body);String action=initial.contract().name(),hash=AuthService.hash(json.write(new TreeMap<>(initial.input())));
        var prior=tx.execute(status->{access(node,attempt,toolId,body);return previous(node,attempt,toolId,body.requestKey(),hash,initial.lease().owner());});if(prior!=null)return prior;
        if(!capacity.tryAcquire())throw new ApiException(429,"OFFICE_BUSY","Office processing capacity is busy");
        try{
            Map<String,Object> source=initial.source();String name=source==null?(String)initial.input().get("name"):(String)source.get("name");String format=documents.format(name);
            if(action.equals("office.read.v1")){var result=documents.inspect(format,Base64.getDecoder().decode((String)source.get("content_base64")),integer(initial.input(),"offset",0,5010),integer(initial.input(),"limit",1,20),initial.input().containsKey("textOffset")?integer(initial.input(),"textOffset",0,1000000):0);access(node,attempt,toolId,body);var value=new LinkedHashMap<>(result);value.put("artifactId",source.get("artifactId"));value.put("version",source.get("version"));value.put("sha256",source.get("sha256"));value.put("businessVerified",false);return value;}
            if(action.equals("office.create.v1") && !format.equals(initial.input().get("format")))throw OfficeDocuments.invalid();
            byte[] content=action.equals("office.create.v1")?documents.create(format,(String)initial.input().get("documentJson")):documents.edit(format,Base64.getDecoder().decode((String)source.get("content_base64")),(String)initial.input().get("documentJson"));
            return tx.execute(status->{var live=access(node,attempt,toolId,body);var already=previous(node,attempt,toolId,body.requestKey(),hash,live.lease().owner());if(already!=null)return already;
                if(db.queryForObject("select count(*) from office_outputs where tenant_id=? and attempt_id=?",Integer.class,node.tenant(),attempt)>=16)throw new ApiException(429,"OFFICE_OUTPUT_LIMIT","At most sixteen Office outputs per attempt");
                String zone=db.queryForObject("select zone from tasks where id=?",String.class,live.lease().taskId());var artifact=artifacts.create(live.lease().owner(),new ArtifactService.Create(name,zone,Base64.getEncoder().encodeToString(content)));String artifactId=(String)artifact.get("artifactId");artifacts.attach(live.lease().owner(),live.lease().taskId(),new ArtifactService.Attachment(artifactId,1));
                db.update("insert into office_outputs values(?,?,?,?,?,?,?,?,?,?,?,?)",AuthService.id(),node.tenant(),live.lease().taskId(),attempt,toolId,body.requestKey(),hash,artifactId,source==null?null:source.get("artifactId"),source==null?null:source.get("version"),source==null?null:source.get("sha256"),clock.millis());
                auth.audit(auth.current(node),"OFFICE_DRAFT_STORED",Map.of("artifactId",artifactId,"taskId",live.lease().taskId(),"operation",action,"format",format));return output(live.lease().owner(),artifactId);
            });
        }finally{capacity.release();}
    }
    private Map<String,Object> previous(Identity node,String attempt,String tool,String key,String hash,Identity owner){var rows=db.queryForList("select request_hash,artifact_id from office_outputs where tenant_id=? and attempt_id=? and tool_version_id=? and request_key=?",node.tenant(),attempt,tool,key);if(rows.isEmpty())return null;var row=rows.get(0);if(!hash.equals(row.get("request_hash")))throw ApiException.conflict("OFFICE_REQUEST_CONFLICT");try{return output(owner,(String)row.get("artifact_id"));}catch(ApiException e){if(e.status==404)throw new ApiException(410,"OFFICE_OUTPUT_DELETED","Original output was deleted; the request key cannot recreate it");throw e;}}
    private Map<String,Object> output(Identity owner,String id){var value=artifacts.read(owner,id,1);return Map.of("artifactId",id,"version",1,"name",value.get("name"),"sha256",value.get("sha256"),"byteSize",value.get("byte_size"),"format",documents.format((String)value.get("name")),"reviewState","UNREVIEWED","visualVerified",false,"businessVerified",false,"formulasEvaluated",((String)value.get("name")).toLowerCase(Locale.ROOT).endsWith(".xlsx"));}
    public Map<String,Object> preview(Identity actor,String id,int version,int offset,int limit,int textOffset){if(version<1)throw OfficeDocuments.invalid();var value=artifacts.read(actor,id,version);if(!capacity.tryAcquire())throw new ApiException(429,"OFFICE_BUSY","Office processing capacity is busy");try{var result=new LinkedHashMap<>(documents.inspect(documents.format((String)value.get("name")),Base64.getDecoder().decode((String)value.get("content_base64")),offset,limit,textOffset));artifacts.read(actor,id,version);result.put("artifactId",id);result.put("version",version);result.put("name",value.get("name"));result.put("sha256",value.get("sha256"));return result;}finally{capacity.release();}}
    public Map<String,Object> outputs(Identity actor,String task,String after,int limit){control.getTask(actor,task);if(after==null || after.length()>64 || limit<1 || limit>50)throw OfficeDocuments.invalid();var rows=db.queryForList("select o.id,o.artifact_id,a.name,v.sha256,v.byte_size,o.source_id,o.source_version,o.source_hash,1 as version from office_outputs o join artifacts a on a.id=o.artifact_id join artifact_versions v on v.artifact_id=a.id and v.version=1 where o.tenant_id=? and o.task_id=? and o.id>? order by o.id limit ?",actor.tenant(),task,after,limit+1);var visible=new ArrayList<Map<String,Object>>();for(var row:rows){try{artifacts.read(actor,(String)row.get("artifact_id"),1);visible.add(row);}catch(ApiException denied){if(denied.status!=404 && denied.status!=403)throw denied;}}boolean more=visible.size()>limit;if(more)visible=new ArrayList<>(visible.subList(0,limit));var result=new LinkedHashMap<String,Object>();result.put("items",visible);if(more)result.put("nextCursor",visible.get(visible.size()-1).get("id"));return result;}
}
